/**
 * The shared classes of storage 2 in an ejected project (ADR 0104 D4, D5; ADR 0112 D3), in `<package>/block/`:
 *
 * - `PlayerStores`, copied from the runtime's (`registry/container/PlayerStores.java`) with the mod's own attachment id;
 * - `DoubleChestBlock`, the runtime's `MsmDoubleChestBlock` without its behaviour driver: vanilla's `ChestBlock` family
 *   with the block's own block entity type (the generated subclass gives `newBlockEntity` and the events), the container
 *   options, comparators per half and the hopper faces (its `HopperFaces` record is a line-by-line copy);
 * - `DoubleChestBlockEntity`, the runtime's `MsmDoubleChestBlockEntity` with events through `BlockEvents`.
 *
 * Minecraft 26.3, Mojang names. The generator's tests compare the copies with the runtime's code lines.
 *
 * @packageDocumentation
 */

/**
 * The source of `PlayerStores.java`, copied from the runtime's `PlayerStores`: the attachment is the mod's own
 * (`<mod id>:player_stores`) and the store key is `BlockWaxing.familyRoot`.
 *
 * @param modPackage - The mod's package (where `BlockWaxing` is).
 * @param modId - The mod id, the attachment's namespace and the logger's name.
 */
export function playerStoresJava(blockPackage: string, modPackage: string, modId: string): string {
  return `// Generated by MCSuperMods: copied from msm_runtime's PlayerStores.
package ${blockPackage};

import com.mojang.serialization.Codec;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.fabricmc.fabric.api.attachment.v1.AttachmentRegistry;
import net.fabricmc.fabric.api.attachment.v1.AttachmentType;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.Identifier;
import net.minecraft.world.Container;
import net.minecraft.world.SimpleContainer;
import net.minecraft.world.SimpleMenuProvider;
import net.minecraft.world.entity.ContainerUser;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.Block;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import ${modPackage}.BlockWaxing;

/**
 * Per-player storage (ADR 0104 D5 and its amendment after B503, X9): a chest with {@code per_player} shows each player
 * their own contents, kept in the persistent Fabric attachment {@code <mod id>:player_stores} on the player, one store
 * per block family ({@link #key}), as vanilla's ender chest keeps one store for every ender chest (limit N7). The
 * attachment is copied on death (a respawned player is a new object) and is the same object after a dimension change; it
 * is saved with the player under {@code fabric:attachments}. Not synced to clients: the menu sends the contents.
 *
 * <p>The block keeps its {@link StorageBlockEntity} for the {@code open} property, the sounds and {@code on_open} and
 * {@code on_close} (its own slots stay empty); hoppers and comparators do not reach the store, as vanilla's ender chest.
 */
public final class PlayerStores {
    private static final String MOD_ID = ${JSON.stringify(modId)};
    private static final Logger LOGGER = LoggerFactory.getLogger(MOD_ID);
    public static final Identifier ID = Identifier.fromNamespaceAndPath(MOD_ID, "player_stores");

    /** Store key (a block id) to the store's slots, empty slots included. */
    public static final AttachmentType<Map<String, List<ItemStack>>> TYPE = AttachmentRegistry.create(ID,
            builder -> builder.persistent(Codec.unboundedMap(Codec.STRING, ItemStack.OPTIONAL_CODEC.listOf())).copyOnDeath());

    private PlayerStores() {}

    /** Registers the attachment type (class initialisation); called while the blocks are registered. */
    public static void register() {
        LOGGER.debug("[{}] registered attachment {}", MOD_ID, TYPE.identifier());
    }

    /**
     * The store key of {@code block}: the id of the first stage of its weathering family (a waxed copy counts as its
     * source), so a chest that ages, is waxed, scraped or struck by lightning keeps showing the same store.
     */
    public static String key(Block block) {
        return BlockWaxing.familyRoot(BuiltInRegistries.BLOCK.getKey(block)).toString();
    }

    /** A copy of {@code player}'s store for {@code key}; empty when the player has none. */
    public static List<ItemStack> contents(Player player, String key) {
        return player.getAttachedOrElse(TYPE, Map.of()).getOrDefault(key, List.of()).stream().map(ItemStack::copy).toList();
    }

    /**
     * Opens {@code player}'s own store of the block at {@code storage} (server side); a locked block sends vanilla's
     * message and opens nothing.
     */
    static void open(StorageBlockEntity storage, Player player) {
        if (!storage.canOpen(player)) {
            return;
        }
        Store store = new Store(storage, player, key(storage.getBlockState().getBlock()));
        player.openMenu(new SimpleMenuProvider((id, inventory, p) -> ContainerMenus.create(storage.spec(), id, inventory, store),
                storage.getDisplayName()));
    }

    /** The store of one player seen through one block: loaded from the attachment, written back on every change and on close. */
    static final class Store extends SimpleContainer {
        private final StorageBlockEntity block;
        private final Player player;
        private final String key;

        Store(StorageBlockEntity block, Player player, String key) {
            super(block.spec().slotCount());
            this.block = block;
            this.player = player;
            this.key = key;
            List<ItemStack> saved = contents(player, key);
            for (int i = 0; i < saved.size() && i < getContainerSize(); i++) {
                super.setItem(i, saved.get(i));
            }
        }

        /** The block entity this store is seen through (its opener counter recognises the store's menu). */
        StorageBlockEntity block() {
            return block;
        }

        @Override
        public void setChanged() {
            super.setChanged();
            save();
        }

        @Override
        public boolean stillValid(Player viewer) {
            return viewer == player && !block.isRemoved() && Container.stillValidBlockEntity(block, viewer);
        }

        @Override
        public void startOpen(ContainerUser user) {
            block.startOpen(user);
        }

        @Override
        public void stopOpen(ContainerUser user) {
            save();
            block.stopOpen(user);
        }

        private void save() {
            Map<String, List<ItemStack>> all = new TreeMap<>(player.getAttachedOrElse(TYPE, Map.of()));
            List<ItemStack> items = new ArrayList<>(getContainerSize());
            for (int i = 0; i < getContainerSize(); i++) {
                items.add(getItem(i).copy());
            }
            all.put(key, List.copyOf(items));
            player.setAttached(TYPE, all);
        }
    }
}
`;
}

/** The source of `DoubleChestBlock.java`: the runtime's `MsmDoubleChestBlock` as a plain abstract class. */
export function doubleChestBlockJava(blockPackage: string): string {
  return `// Generated by MCSuperMods: msm_runtime's MsmDoubleChestBlock (registry/container) as a plain class.
package ${blockPackage};

import java.util.function.Supplier;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.Container;
import net.minecraft.world.WorldlyContainer;
import net.minecraft.world.WorldlyContainerHolder;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.LevelAccessor;
import net.minecraft.world.level.block.ChestBlock;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.entity.BlockEntityType;
import net.minecraft.world.level.block.entity.ChestBlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.sounds.SoundEvents;

/**
 * A chest with {@code double: true} (ADR 0104 D4 and its amendment after B503, X8): vanilla's {@link ChestBlock} family with
 * the block's own block entity type (a {@link DoubleChestBlockEntity}; the generated subclass makes it in
 * {@link #newBlockEntity}, so vanilla's chest type is never made). Two placed side by side join through vanilla's
 * {@code type} state ({@code single}, {@code left}, {@code right}), share one six-row menu and each half keeps and drops its
 * own 27 slots; sneak-placing keeps them apart; comparators and hoppers work per half as vanilla's. Block models per
 * {@code type} draw it (no block entity renderer). It always has vanilla's {@code waterlogged} property, as vanilla's chest.
 *
 * <p>The container options: {@code open_sound} and {@code close_sound} (the barrel's by default, as every MSM container),
 * {@code on_open} and {@code on_close} (once per opening of the pair), {@code comparator}, and {@code hoppers}: the block is
 * a {@link WorldlyContainerHolder}, which hoppers and Fabric's item transfer ask first, answering vanilla's container for
 * the chest (both halves when joined) with every face or, with {@code hoppers: false}, none.
 */
public abstract class DoubleChestBlock extends ChestBlock implements WorldlyContainerHolder {
    private final ContainerSpec spec;

    protected DoubleChestBlock(ContainerSpec spec, Supplier<BlockEntityType<? extends ChestBlockEntity>> type, Properties properties) {
        super(type, ContainerOpeners.sound(spec.openSound(), SoundEvents.BARREL_OPEN),
                ContainerOpeners.sound(spec.closeSound(), SoundEvents.BARREL_CLOSE), properties);
        this.spec = spec;
    }

    /** {@code msm:container}. */
    public ContainerSpec spec() {
        return spec;
    }

    /** The block's own {@link DoubleChestBlockEntity}. */
    @Override
    public abstract BlockEntity newBlockEntity(BlockPos pos, BlockState state);

    // Comparators: vanilla's per half unless comparator is false; hoppers through the holder below.

    @Override
    protected boolean hasAnalogOutputSignal(BlockState state) {
        return spec.comparator();
    }

    @Override
    public WorldlyContainer getContainer(BlockState state, LevelAccessor level, BlockPos pos) {
        Container chest = level instanceof Level l ? ChestBlock.getContainer(this, state, l, pos, true) : null;
        return new HopperFaces(chest, spec.hoppers());
    }

    /** Vanilla's chest container (one half or both) seen by hoppers: every slot from every face, or none. */
    private record HopperFaces(Container chest, boolean open) implements WorldlyContainer {
        private static final int[] NONE = new int[0];

        @Override
        public int[] getSlotsForFace(Direction side) {
            if (!open || chest == null) {
                return NONE;
            }
            int[] all = new int[chest.getContainerSize()];
            for (int i = 0; i < all.length; i++) {
                all[i] = i;
            }
            return all;
        }

        @Override
        public boolean canPlaceItemThroughFace(int slot, ItemStack stack, Direction side) {
            return open && chest != null && chest.canPlaceItem(slot, stack);
        }

        @Override
        public boolean canTakeItemThroughFace(int slot, ItemStack stack, Direction side) {
            return open && chest != null;
        }

        @Override
        public int getContainerSize() {
            return chest == null ? 0 : chest.getContainerSize();
        }

        @Override
        public boolean isEmpty() {
            return chest == null || chest.isEmpty();
        }

        @Override
        public ItemStack getItem(int slot) {
            return chest == null ? ItemStack.EMPTY : chest.getItem(slot);
        }

        @Override
        public ItemStack removeItem(int slot, int count) {
            return chest == null ? ItemStack.EMPTY : chest.removeItem(slot, count);
        }

        @Override
        public ItemStack removeItemNoUpdate(int slot) {
            return chest == null ? ItemStack.EMPTY : chest.removeItemNoUpdate(slot);
        }

        @Override
        public void setItem(int slot, ItemStack stack) {
            if (chest != null) {
                chest.setItem(slot, stack);
            }
        }

        @Override
        public int getMaxStackSize() {
            return chest == null ? 64 : chest.getMaxStackSize();
        }

        @Override
        public boolean canPlaceItem(int slot, ItemStack stack) {
            return chest != null && chest.canPlaceItem(slot, stack);
        }

        @Override
        public void setChanged() {
            if (chest != null) {
                chest.setChanged();
            }
        }

        @Override
        public boolean stillValid(Player player) {
            return chest != null && chest.stillValid(player);
        }

        @Override
        public void clearContent() {
            if (chest != null) {
                chest.clearContent();
            }
        }
    }
}
`;
}

/** The source of `DoubleChestBlockEntity.java`: the runtime's `MsmDoubleChestBlockEntity`, events through `BlockEvents`. */
export function doubleChestBlockEntityJava(blockPackage: string): string {
  return `// Generated by MCSuperMods: msm_runtime's MsmDoubleChestBlockEntity (registry/container) as a plain class.
package ${blockPackage};

import java.util.Optional;
import net.minecraft.core.BlockPos;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.Identifier;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.ContainerUser;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.block.ChestBlock;
import net.minecraft.world.level.block.entity.BlockEntityType;
import net.minecraft.world.level.block.entity.ChestBlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.ChestType;

/**
 * The block entity of a {@link DoubleChestBlock} (ADR 0104 D4): vanilla's {@link ChestBlockEntity} (27 slots, loot tables,
 * custom names, {@code lock}, the opener counter and vanilla's saved shape) with the block's own type. Its default name is
 * the block's; {@code on_open} and {@code on_close} fire with the player as self and other, once per opening of a joined
 * pair (from the half that is not {@code right}: vanilla opens both halves of the six-row menu).
 */
public class DoubleChestBlockEntity extends ChestBlockEntity {
    public DoubleChestBlockEntity(BlockEntityType<?> type, BlockPos pos, BlockState state) {
        super(type, pos, state);
    }

    @Override
    protected Component getDefaultName() {
        return Component.translatable(getBlockState().getBlock().getDescriptionId());
    }

    @Override
    public void startOpen(ContainerUser user) {
        boolean fires = firesFor(user);
        super.startOpen(user);
        if (fires && getBlockState().getBlock() instanceof DoubleChestBlock block) {
            fire(block, block.spec().onOpen(), (Player) user.getLivingEntity());
        }
    }

    @Override
    public void stopOpen(ContainerUser user) {
        boolean fires = firesFor(user);
        super.stopOpen(user);
        if (fires && getBlockState().getBlock() instanceof DoubleChestBlock block) {
            fire(block, block.spec().onClose(), (Player) user.getLivingEntity());
        }
    }

    private boolean firesFor(ContainerUser user) {
        LivingEntity entity = user.getLivingEntity();
        BlockState state = getBlockState();
        return !isRemoved() && entity instanceof Player && !entity.isSpectator()
                && !(state.hasProperty(ChestBlock.TYPE) && state.getValue(ChestBlock.TYPE) == ChestType.RIGHT);
    }

    private void fire(DoubleChestBlock block, Optional<Identifier> event, Player player) {
        if (event.isPresent() && getLevel() instanceof ServerLevel server && block instanceof BlockEvents events) {
            events.fireEvent(event.get(), server, getBlockPos(), player);
        }
    }
}
`;
}
